int *ptr = &N;
printf("%d\n", *ptr); // 1000
*ptr = 280;            // doi qua con tro
printf("%d\n", N);    // 280 (N da doi theo)

int N = 1000;
int *ptr1 = &N;
int *ptr2 = &N;
int *ptr3 = ptr1;  // gan gia tri cua ptr1 (chinh la &N)

*ptr1 = 100; // N = 100
*ptr2 = 200; // N = 200
*ptr3 = 300; // N = 300, ca 3 con tro deu tro ve N = 300

void change(int *x) {
    *x = 1000; // doi truc tiep bien ma x tro toi
}

int N = 28;
change(&N);           // truyen dia chi cua N
printf("%d\n", N);  // 1000

void my_swap(int *x, int *y) {
    int tmp = *x;
    *x = *y;
    *y = tmp;
}

int a = 100, b = 200;
my_swap(&a, &b);   // a = 200, b = 100

